SELECT year(l.origination_date), ROUND(100.0*COUNT(*) FILTER (WHERE s.months_on_book=3 AND s.days_past_due>=30)/NULLIF(COUNT(*) FILTER (WHERE s.months_on_book=3),0),2), ROUND(100.0*COUNT(*) FILTER (WHERE s.months_on_book=6 AND s.days_past_due>=30)/NULLIF(COUNT(*) FILTER (WHERE s.months_on_book=6),0),2), ROUND(100.0*COUNT(*) FILTER (WHERE s.months_on_book=12 AND s.days_past_due>=30)/NULLIF(COUNT(*) FILTER (WHERE s.months_on_book=12),0),2), ROUND(100.0*COUNT(*) FILTER (WHERE s.months_on_book=24 AND s.days_past_due>=30)/NULLIF(COUNT(*) FILTER (WHERE s.months_on_book=24),0),2) FROM loan_monthly_snapshot s JOIN loan l USING (loan_id) WHERE s.loan_status<>'Closed' AND year(l.origination_date) BETWEEN 2020 AND 2023 GROUP BY 1 ORDER BY 1
